func testPermissaoRecursoToManyRemoveOpUfiUsuarioFilials(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a PermissaoRecurso
	var b, c, d, e UsuarioFilial

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, permissaoRecursoDBTypes, false, strmangle.SetComplement(permissaoRecursoPrimaryKeyColumns, permissaoRecursoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*UsuarioFilial{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, usuarioFilialDBTypes, false, strmangle.SetComplement(usuarioFilialPrimaryKeyColumns, usuarioFilialColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	err = a.AddUfiUsuarioFilials(ctx, tx, true, foreigners...)
	if err != nil {
		t.Fatal(err)
	}

	count, err := a.UfiUsuarioFilials().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 4 {
		t.Error("count was wrong:", count)
	}

	err = a.RemoveUfiUsuarioFilials(ctx, tx, foreigners[:2]...)
	if err != nil {
		t.Fatal(err)
	}

	count, err = a.UfiUsuarioFilials().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 2 {
		t.Error("count was wrong:", count)
	}

	if len(b.R.PrePermissaoRecursos) != 0 {
		t.Error("relationship was not removed properly from the slice")
	}
	if len(c.R.PrePermissaoRecursos) != 0 {
		t.Error("relationship was not removed properly from the slice")
	}
	if d.R.PrePermissaoRecursos[0] != &a {
		t.Error("relationship was not added properly to the foreign struct")
	}
	if e.R.PrePermissaoRecursos[0] != &a {
		t.Error("relationship was not added properly to the foreign struct")
	}

	if len(a.R.UfiUsuarioFilials) != 2 {
		t.Error("should have preserved two relationships")
	}

	// Removal doesn't do a stable deletion for performance so we have to flip the order
	if a.R.UfiUsuarioFilials[1] != &d {
		t.Error("relationship to d should have been preserved")
	}
	if a.R.UfiUsuarioFilials[0] != &e {
		t.Error("relationship to e should have been preserved")
	}
}

